// ViewStack — Adw.ViewStack
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles it with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ViewStackProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Adw.ViewStack */
  enableTransitions?: boolean

  /** gboolean, from Adw.ViewStack */
  hhomogeneous?: boolean

  /** guint, from Adw.ViewStack */
  transitionDuration?: number

  /** gboolean, from Adw.ViewStack */
  vhomogeneous?: boolean

  /** Gtk.Widget, from Adw.ViewStack */
  visibleChild?: ReactNode

  /** utf8, from Adw.ViewStack */
  visibleChildName?: string
}

export function ViewStack({ className, children }: ViewStackProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
